"""Generate the new report and two-page thesis directly from saved v3 measurements."""
import argparse
import json
from pathlib import Path
from xml.sax.saxutils import escape
from pypdf import PdfReader
from build_learned_report import block,pdf,docx,ST

ROOT=Path(__file__).resolve().parents[1]
BASE=ROOT/'experiments/evidence/instance_v3'
SCENE=ROOT/'experiments/evidence/instance_scenes_v3'
OUT=ROOT/'output/research_instance_v3'
LABELS=json.loads((BASE/'labels.json').read_text(encoding='utf-8'))


def read(path): return json.loads(path.read_text(encoding='utf-8'))
def percent(x): return f'{100*x:.2f}'


def main(cost_analysis=False):
    global OUT
    OUT=ROOT/('output/research_instance_v3_cost' if cost_analysis else 'output/research_instance_v3')
    OUT.mkdir(exist_ok=True,parents=True)
    summary=read(BASE/'test_summary.json'); frozen=read(BASE/'frozen_thresholds.json'); stats=read(BASE/'statistics.json')
    scene=read(SCENE/'summary.json'); verification=read(BASE/'verification.json')
    primary=next(r for r in summary if r['method']==frozen['selected_visual']); gated=next(r for r in summary if r['method']=='conditional_text')
    success=gated['fpr']<primary['fpr'] and gated['tpr']>=frozen['recall_budget'] and gated['tpr']>=primary['tpr']
    conclusion='Заранее заданный практический критерий выполнен на этой выборке.' if success else 'Заранее заданный практический критерий полезного превосходства не выполнен.'
    cost=None
    if cost_analysis:
        cost=read(ROOT/'experiments/evidence/instance_v3_cost/analysis.json')
        conclusion='Наблюдается полезный компромисс: пять устранённых ложных принятий ценой одного пропуска. Исходный критерий без потери полноты не выполнен.'
    significance='H0 отвергнута для основного направленного сравнения.' if stats['sign_p']<.05 else 'H0 не отвергается; это не доказательство равенства методов.'
    effect=f'Снижение FPR: {100*stats["fpr_reduction"]:.2f} п.п.; 95% парный bootstrap по категориям [{100*stats["ci95"][0]:.2f}; {100*stats["ci95"][1]:.2f}] п.п. Изменение полноты: {100*stats["recall_difference"]:.2f} п.п. Односторонний знаковый тест p={stats["sign_p"]:.4f}. {significance}'
    headline=f'На новом тесте выбранный визуальный метод дал полноту {percent(primary["tpr"])}% и FPR чужих ID {percent(primary["fpr"])}%; с условным текстом — {percent(gated["tpr"])}% и {percent(gated["fpr"])}%. {conclusion}'
    def table_rows(names=None):
        selected=summary if names is None else [next(r for r in summary if r['method']==n) for n in names]
        return [['Метод','R %','FPR %','P %','F1']]+[[LABELS[r['method']],percent(r['tpr']),percent(r['fpr']),percent(r['precision']),f'{r["f1"]:.3f}'] for r in selected]
    def scene_rows():
        return [['Метод','TP','FP','FN','TN','R %','FPR отсутств. %','IoU']]+[[('Визуальный' if r['method']=='visual' else 'С текстом'),r['tp'],r['fp'],r['fn'],r['tn'],percent(r['recall']),percent(r['absent_fpr']),f'{r["mean_iou"]:.3f}'] for r in scene]
    B=[]
    def add(kind,text=None,**kwargs): B.append(block(kind,text,**kwargs))
    add('title','Диагностика поиска экземпляра и проверка условной текстовой оценки')
    add('p','Отчёт по следующему этапу исследования. В. О. Шабашев. 11 октября 2026 года. Предыдущие результаты сохранены; для новой оценки использована другая база изображений.')
    add('p',headline); add('p',effect)
    add('head','Что ограничивало прежний результат')
    add('p','Разбор сохранённых предсказаний GMOT-40: из 28 кадров в 15 отсутствует правильный кандидат YOLO при IoU≥0,5. Из 13 оставшихся DINO выбирает цель в 7. Визуальный порог эти 7 не теряет; текст отклоняет одну правильную рамку. У сиамского MLP правильный выбор также 7 из 13, но визуальный порог теряет одну цель. Следовательно, семантический фильтр не может исправить большую часть пропусков генератора.')
    add('image',path=BASE/'error_decomposition.png',height=220)
    add('small','Рисунок 1. Взаимоисключающие причины исходов на прежних кадрах. Это диагностика данных разработки, не новый тест.')
    add('break'); add('head','Новые данные и разбиение')
    add('table',rows=[['Часть','Новые ID','RGB-вырезки'],['Обучение',24,120],['Валидация',24,120],['Тест',24,120],['Дополнительное старое обучение GMOT',112,560]],widths=[285,90,90])
    add('p','Washington RGB-D Object Dataset содержит физически определённые экземпляры и видео при разных высотах камеры [1]. Выбраны 12 категорий по правилу, зафиксированному до признаков и оценок. В каждой шесть ID разделены 2/2/2. Единственный эталон — первый кадр первого видео, четыре кандидата — равномерные позиции следующего видео. Новые validation/test ID не используются для обучения.')
    add('p','Категории: мячи, сладкий перец, батарейки, пакеты продуктов, коробки продуктов, консервные банки, банки продуктов, чеснок, клеящие карандаши, лапша быстрого приготовления, лимоны, маркеры. Это расширяет предметную область, но не проверяет здания и не доказывает поиск любого объекта.')
    add('p','Новый тест: 24 запроса и 192 пары, 96 положительных и 96 отрицательных. Отрицательный кандидат — другой физический ID той же категории. Общая установка съёмки сохраняется; разные видео не означают произвольные независимые сцены. Часть вырезок мала: у 140 из 360 меньшая сторона ниже 64 пикселей, у 6 ниже 32. Используются готовые RGB-вырезки источника, без собственного удаления фона. Синтетические примеры не добавлялись.')
    add('p','Отдельная проверка сцен: 4 новых ID, 2 тестовых сцены, 30 уникальных изображений и 48 пар запрос/кадр. В 16 парах цель видима, в 32 не имеет видимой аннотации. Эталон снят на поворотной платформе. Категории сцен исключены из нового обучения; ID валидационных сцен исключены из тестовых запросов. Неразмеченное присутствие за перекрытием не объявляется физическим отсутствием.')
    add('p','Официальный источник разрешает некоммерческие исследовательские и образовательные применения. Сохранены URL, SHA256 архивов/снимков и ZIP CRC. Из большого ZIP скачаны только нужные записи; исходные изображения не распространяются в Git. Архив background сохранён для будущих опытов, но в данные этого теста не включён.')
    add('break'); add('head','Метод и обучение')
    add('p','Сохраняется исходный авторский проектор из mahalanobis-concept-drift: Linear/BatchNorm/GELU/dropout, размеры 384→256→128→64. Замороженные DINOv2-small и MiniLM дают признаки изображения и независимого описания Qwen3.5:0.8b. Визуальный и текстовый проекторы обучены отдельно. Совместно используются 112 старых GMOT ID и 24 новых train ID: всего 136 обучающих экземпляров.')
    add('p','Изменение обучения: для каждого якоря внутри обучающего блока выбираются самый далёкий положительный и ближайший отрицательный пример. Используется batch-hard triplet [2], L2-нормированный выход, отступ 0,2, Adam 0,001, 30 эпох, seed 2027. Это известный принцип обучения, не новая архитектура. Тест не участвует в выборе эпох, seed или ковариации.')
    add('p','До обучения добавлен контроль со случайными тройками на тех же данных, с теми же эпохами, нормировкой, инициализацией и порядком блоков. Он отделяет влияние выбора трудных примеров от остальных условий обучения. Эта дополнительная абляция не меняет основную гипотезу или выбор визуального метода для неё.')
    add('image',path=BASE/'mahalanobis_formula.png',height=45)
    add('p','Полная ковариация Ledoit-Wolf оценивается по симметричным разностям обучающих пар одного ID; добавляется 10⁻⁴I. Сравниваются косинус, диагональная и полная ковариации на одинаковых признаках. Ковариация единственного тестового эталона не оценивается. Термин «многомодальность» исходного проекта относится к классам текстов; здесь применяется перенос общей метрики к новым экземплярам.')
    add('p',f'Ориентир R*={percent(frozen["recall_budget"])}% равен среднему validation recall SIFT и DINO при их максимальном macro-F1. Затем пороги минимизируют FPR при R≥R*. Этот ориентир зависит от состава базовых методов и не является универсальным стандартом. На валидации выбран визуальный метод: {LABELS[frozen["selected_visual"]]}.')
    add('p','Текст вызывается только в области неоднозначных визуальных расстояний. Четыре варианта границы — квантили положительных validation-расстояний 0, 0,5, 0,75 и 1. Порог текста также выбирается только на validation. Если пригодного описания нет, комбинированный метод возвращается к визуальному решению; отдельный текстовый метод отказывается. Отключение фильтра допустимо и сравнивается явно.')
    add('p','Ограничение ориентира полноты: максимум F1 слабого SIFT на сбалансированной валидации достигается при принятии всех пар (R=100%, FPR=100%). У DINO в собственной точке максимума F1 R=84,375%. Их среднее поднимает требуемую полноту до 92,1875% и способствует высокому FPR. После раскрытия теста это правило не менялось. В следующем протоколе следует заранее исключить вырожденный baseline из определения ориентира.')
    add('break'); add('head','Результаты нового теста')
    add('table',rows=table_rows(),widths=[225,60,60,60,60])
    add('small','Таблица 1. Макрооценки по 12 категориям. R — полнота, P — precision. FPR — принятие пары с другим ID. Пропорция положительных пар 1/2 отличается от 1/4 в прежнем опыте: precision между этими опытами напрямую не сравнивается.')
    add('image',path=BASE/'operating_points.png',height=205)
    add('p',effect)
    add('p','Фильтр устранил 5 ложных принятий, но потерял 1 правильное. Визуальный MLP с трудными примерами снижает FPR, однако его полнота ниже установленного ориентира, поэтому безусловного улучшения нет. Контроль случайных троек имеет другой компромисс ошибок; он не переизбирается основным методом по тестовым результатам. Для текстового MLP полная ковариация не показала превосходства над косинусом в этих рабочих точках.')
    add('p',f'Условный фильтр включён: {"да" if frozen["gate"]["enabled"] else "нет"}. Доля тестовых пар, для которых политика запрашивает текст: {percent(gated["text_requested_fraction"])}%. Это доля запросов по политике, не измеренное ускорение всей онлайн-системы. Описания для контролируемых сравнений подготовлены заранее для всех вырезок.')
    add('break'); add('head','Кривые ошибок и различимость признаков')
    add('image',path=BASE/'roc_pr.png',height=230)
    add('small','Рисунок 2. Кривые по всем парам (micro); условный фильтр показан фиксированной точкой с micro-precision. В таблице 1 precision усредняется по категориям (macro). Тестовые кривые не используются для перенастройки порогов.')
    add('image',path=BASE/'confusion.png',height=190)
    add('small','Рисунок 3. Абсолютные числа решений основного сравнения. Кадры одного объекта не считаются независимыми статистическими наблюдениями.')
    add('break'); add('head','Обучение и текстовые расстояния')
    add('image',path=BASE/'training.png',height=180)
    add('image',path=BASE/'distances.png',height=200)
    add('small','Рисунок 4. Обучающая потеря и распределения расстояний. Низкая обучающая потеря сама по себе не подтверждает обобщение. Постоянные отказы не рисуются как конечное расстояние.')
    add('p','Визуальная проверка фиксированных пяти наиболее уверенных ложных принятий прежнего текстового метода показала очень похожие мячи и насекомых, а также малые размытые светящиеся объекты. Описания перечисляли общие форму, цвет и части; надёжные индивидуальные признаки по этим примерам выделить трудно. Это качественная диагностика, не независимая ручная разметка и не оценка частоты галлюцинаций.')
    add('p','На новых обучающих кадрах также встречаются ошибочные названия: ball_1_1_1_crop описан как чашка. Такой пример показывает риск текстового посредника, но один случай не позволяет оценить его общую частоту. Размер исходных вырезок и качество описаний необходимо анализировать отдельно от ковариации.')
    add('break'); add('head','Перенос на целые сцены')
    add('table',rows=scene_rows(),widths=[100,32,32,32,32,55,100,55])
    add('small','Таблица 2. 48 решений на двух сценах. TP требует IoU≥0,5; неправильная рамка на кадре присутствия даёт FP+FN. IoU усредняется по 16 кадрам присутствия, отказ равен нулю. FPR отсутствия — FP на 32 парах без видимой аннотации цели.')
    add('p',f'YOLOv8n предложил правильную рамку в {percent(scene[0]["proposal_recall"])}% случаев присутствия. Рамки общие для обоих методов. Перенесены пороги из опыта с вырезками: эта проверка измеряет доменный сдвиг к ошибочным предложениям детектора. Начальная рамка цели не предоставлялась.')
    add('image',path=BASE/'scene_results.png',height=215)
    add('p','Из четырёх выбранных кадров присутствия каждого запроса крайние могут показывать частичный вход или выход объекта; такие кадры не удалялись по результатам. Один кадр может участвовать с разными запросами, поэтому 48 решений не являются 48 независимыми сценами. На этой части статистическое превосходство не заявляется.')
    add('break'); add('head','Воспроизводимость и вывод')
    add('p',headline)
    add('p',f'Независимый пересчёт сохранённых решений: {verification["pair_decisions"]} парных и {verification["scene_decisions"]} сценовых решений; статус {verification["status"]}. Проверены непересечение ID, отсутствие новых validation/test ID в обучении, TP/FP/FN/TN и IoU по координатам. Это отдельный пересчёт в том же проекте, не репликация сторонней лабораторией.')
    execution=[]
    for name in ['caption','features','train','calibrate','evaluate','scene_proposals','scene_visual','scene_describe','scene_evaluate']:
        p=BASE/(name+'_execution.json')
        if p.exists():
            r=read(p); execution.append([name,f'{r["wall_sec"]:.1f}',f'{r["peak_tree_rss_bytes"]/1024**2:.0f}',r['returncode']])
    add('table',rows=[['Стадия','Время, с','RSS, МиБ','Код выхода']]+execution,widths=[200,90,90,85])
    add('p','CPU Intel i5-1240P, около 8 ГБ RAM, четыре потока моделей. VLM и кодировщики запускались последовательно. RSS дерева процесса не является полным пиком памяти компьютера и может не включать внешний Ollama. Время подготовки описаний не выдаётся за FPS трекера. Все данные, веса и стадии имеют контрольные точки; точные команды — experiments/INSTANCE_V3_REPRODUCE.md.')
    add('p','Подтверждённый вклад — измеренное разделение ошибок генератора, сопоставления и фильтра, адаптация исходного MLP с трудными отрицательными примерами и новый протокол переноса с учётом отказов. Приоритет новой архитектуры не заявляется. Нельзя утверждать универсальный выигрыш Махаланобиса, работоспособность на зданиях или улучшение непрерывного сопровождения. Следующий опыт должен расширять число независимых сцен и улучшать предложения рамок; текущий новый тест после этой оценки тоже становится известным.')
    references=[
        '[1] Lai K., Bo L., Ren X., Fox D. A Large-Scale Hierarchical Multi-View RGB-D Object Dataset. ICRA, 2011. https://rgbd-dataset.cs.washington.edu/',
        '[2] Hermans A., Beyer L., Leibe B. In Defense of the Triplet Loss for Person Re-Identification. 2017. https://arxiv.org/abs/1703.07737',
        '[3] Oquab M. et al. DINOv2: Learning Robust Visual Features without Supervision. https://arxiv.org/abs/2304.07193',
        '[4] Reimers N., Gurevych I. Sentence-BERT. EMNLP-IJCNLP, 2019. https://aclanthology.org/D19-1410/',
        '[5] Ledoit O., Wolf M. A well-conditioned estimator for large-dimensional covariance matrices. J. Multivariate Analysis, 88(2), 2004, 365–411.',
        '[6] Шабашев В. О. Mahalanobis Concept Drift Detector. https://github.com/sha-bash/mahalanobis-concept-drift, commit fb3bccd1e4a0768fcfb15817fb4fcb809f2af4ad.',
        '[7] Geifman Y., El-Yaniv R. SelectiveNet: A Deep Neural Network with an Integrated Reject Option. ICML, 2019. https://arxiv.org/abs/1901.09192. Связанная постановка отказа; эта сеть здесь не реализуется.',
    ]
    add('break'); add('head','Источники и ограничения интерпретации')
    for reference in references: add('p',escape(reference))
    add('p','Использованы первоисточники данных и методов. Выборка RGB-D организована по физическим экземплярам; опубликованные результаты исходной статьи датасета не подставляются вместо наших измерений. Пересечение изображений с предобучением больших кодировщиков неизвестно. Условия использования допускают некоммерческое исследование; снимки не добавлены в Git.')
    add('image',path=BASE/'per_category.png',height=230)
    add('small','Рисунок 5. Изменение FPR по категориям. При малом числе категорий доверительные интервалы имеют ограниченную надёжность. Нулевой эффект фильтра допустим и не скрывается.')
    if cost_analysis:
        add('break'); add('head','Выводы при повышенной цене ложного принятия')
        add('p','Дополнительный анализ выполнен после получения тестовых результатов по уточнённому приоритету задачи. Модели, пороги, решения и исходная гипотеза не изменены. Результат поддерживает роль текста как дополнительного средства отказа: устранены 6,49% прежних ложных принятий при потере 1,08% прежних правильных совпадений. Среди шести отклонённых пар пять отрицательные по разметке; это не оценка точности на новых независимых объектах.')
        add('p','Пусть c=C_FP/C_FN — относительная цена ложного принятия, цена пропуска равна единице. На этих 192 парах L_виз=77c+3, L_фильтр=72c+4; выигрыш L_виз−L_фильтр=5c−1. Он положителен при c>0,2, в частности при приоритетном снижении ложных принятий (c>1). Стоимость вычисления текста в эту величину не входит.')
        add('table',rows=[['Цена FP / FN','Без фильтра','С фильтром','Снижение, %']]+[[r['fp_cost'],r['baseline_loss'],r['filtered_loss'],f'{100*r["relative_reduction"]:.2f}'] for r in cost['costs']],widths=[150,100,100,115])
        add('image',path=ROOT/'experiments/evidence/instance_v3_cost/cost_sensitivity.png',height=180)
        add('small','Рисунок 6. Разведочный анализ стоимости ошибок. Значения цены 1, 2, 5 и 10 иллюстративны. Интервалы получены парным bootstrap по 12 категориям; они включают ноль. Это не новая подтверждающая проверка гипотезы.')
